{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "The closest oxathiolane cytidine analogue dOTC achieved 16.5% CSF/serum after oral dosing in rats and was classified as BBB-permeable; this direct in vivo CNS-penetration evidence transfers to the query because both share the cytosine base and oxathiolane scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cytarabine, a cytidine nucleoside, reached a mean CSF/plasma ratio of 0.58 in dogs after i.v. bolus, demonstrating that polar cytidine analogs can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In humans, cytarabine CSF levels were approximately 40% of plasma during systemic infusion, confirming meaningful CNS access for this nucleoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "L-2'-Fd4C, a fluorinated cytidine analog, was detected in monkey CSF after oral dosing at levels exceeding the HIV EC50, showing functional CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PSI-6130, another cytidine analog, was detected in rhesus monkey CSF after oral administration, supporting CNS penetration for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Gemcitabine, a related cytidine analog, showed poor brain penetration (CSF/plasma 6.7%, brain AUC <0.1), indicating that not all cytidine analogs achieve meaningful CNS exposure; however, its 2',2'-difluoro ribose differs substantially from the query's oxathiolane.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: despite low passive permeability estimates, the query is a cytidine/oxathiolane nucleoside closely related to dOTC, which showed 16.5% CSF/serum in rats and was classified as BBB-permeable; additional cytidine analogs (ara-C, PSI-6130, L-2'-Fd4C) demonstrate meaningful CNS access. Contradictory gemcitabine data are less transferable due to structural differences.",
  "evidence_gaps": [
    "No direct experimental CSF/plasma or brain uptake measurement for the exact query molecule in the provided evidence set; closest direct analog is dOTC with 16.5% CSF/serum.",
    "Potential efflux transporter effects at the BBB for the query are not directly quantified.",
    "Human clinical CNS penetration data for lamivudine/query are not included in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

